// Temporaerer Bild-Bridge fuer den Repo-Upload der Finanzberater-Screenshots.
// Liefert die Bilder als Binary, damit der n8n-Webhook commit-image sie holen kann.
const IMG = {
  baufi: "",
  edelmetall: "",
  immo: "",
  kindersparplan: "",
  privatkredite: "",
};

exports.handler = async (event) => {
  const n = (event.queryStringParameters || {}).n;
  if (!IMG[n]) return { statusCode: 404, body: "not found" };
  return {
    statusCode: 200,
    headers: { "Content-Type": "image/webp", "Cache-Control": "no-store" },
    body: IMG[n],
    isBase64Encoded: true
  };
};
